recipes.push({name:'Запечённая овсянка с яблоком',time:35,ing:{oats:85,milk:230,apple:180,egg:50,oil:4},steps:['Смешайте хлопья, молоко и яйцо. Добавьте нарезанное яблоко.','Смажьте форму маслом и переложите смесь.','Запекайте при 180 °C около 30 минут до полного схватывания яичной смеси.']},{name:'Картофель с творогом и яйцом',time:25,ing:{potato:350,curd:200,egg:100,milk:70,oil:12},steps:['Отварите картофель до мягкости. Слейте воду и разомните с молоком.','На сковороде с маслом приготовьте яйца до полного схватывания.','Подайте картофель с яйцами и творогом.']},{name:'Картофельная запеканка с овощами',time:50,ing:{potato:350,egg:150,milk:150,carrot:80,onion:40,oil:15},steps:['Тонко нарежьте картофель, морковь и лук.','Смажьте форму маслом. Разложите овощи и залейте смесью яиц и молока.','Запекайте при 180 °C около 45 минут до мягкости картофеля и полного схватывания яиц.']});
